+/* ==========================================================================
+   Content Sections Module
+   Handles content section layouts, headers, about section, exhibitions, and events
+   ========================================================================== */
+
+/* ==========================================================================
+   Content Section Base
+   ========================================================================== */
+
+.content-section {
+    padding: var(--spacing-section) 0;
+}
+
+.content-section:nth-child(even) {
+    background-color: var(--color-background-alt);
+}
+
+/* ==========================================================================
+   Section Headers
+   ========================================================================== */
+
+.section-header {
+    text-align: left;
+    max-width: 800px;
+    margin: 0 auto var(--spacing-lg);
+}
+
+.section-title {
+    font-size: var(--font-size-large);
+    font-weight: var(--font-weight-bold);
+    color: var(--color-primary);
+    margin-bottom: var(--spacing-sm);
+}
+
+.section-subtitle {
+    font-size: var(--font-size-base);
+    color: var(--color-text-light);
+    max-width: 600px;
+    margin: 0 auto;
+}
+
+/* ==========================================================================
+   Section Content
+   ========================================================================== */
+
+.section-content {
+    max-width: 800px;
+    margin: 0 auto;
+}
+
+.section-content p {
+    text-align: left;
+    margin-bottom: var(--spacing-md);
+}
+
+.section-content p:last-child {
+    margin-bottom: 0;
+}
+
+/* ==========================================================================
+   About Section
+   ========================================================================== */
+
+.about-section .section-content {
+    display: flex;
+    flex-direction: column;
+    gap: var(--spacing-lg);
+}
+
+.about-image {
+    display: block;
+    max-width: 280px;
+    height: auto;
+    margin: 0 auto;
+    border-radius: var(--radius-md);
+    box-shadow: var(--shadow-md);
+}
+
+/* ==========================================================================
+   Exhibitions List
+   ========================================================================== */
+
+.exhibitions-list {
+    list-style: none;
+    padding-left: 0;
+    margin-bottom: var(--spacing-md);
+}
+
+.exhibitions-list li {
+    position: relative;
+    padding-left: var(--spacing-md);
+    margin-bottom: var(--spacing-sm);
+}
+
+.exhibitions-list li::before {
+    content: "•";
+    position: absolute;
+    left: 0;
+    color: var(--color-accent);
+    font-weight: var(--font-weight-bold);
+}
+
+.exhibitions-list ul {
+    margin-top: var(--spacing-xs);
+    margin-bottom: var(--spacing-sm);
+    padding-left: var(--spacing-md);
+    list-style: disc;
+}
+
+/* ==========================================================================
+   Event Cards
+   ========================================================================== */
+
+.event-card {
+    background-color: var(--color-background);
+    border: 1px solid var(--color-border);
+    border-radius: var(--radius-md);
+    padding: var(--spacing-md);
+    margin-bottom: var(--spacing-md);
+}
+
+.event-card:last-child {
+    margin-bottom: 0;
+}
+
+.event-date {
+    font-weight: var(--font-weight-bold);
+    color: var(--color-accent);
+    margin-bottom: var(--spacing-xs);
+}
+
+.event-title {
+    font-size: var(--font-size-medium);
+    font-weight: var(--font-weight-bold);
+    margin-bottom: var(--spacing-xs);
+}
+
+.event-details {
+    color: var(--color-text-light);
+    font-size: var(--font-size-base);
+}
+
+/* ==========================================================================
+   Event Article Styling
+   ========================================================================== */
+
+.event {
+    background-color: var(--color-background);
+    border: 1px solid var(--color-border);
+    border-radius: var(--radius-md);
+    padding: var(--spacing-md);
+    margin-bottom: var(--spacing-md);
+    box-shadow: var(--shadow-sm);
+    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
+}
+
+.event:last-child {
+    margin-bottom: 0;
+}
+
+.event:hover,
+.event:focus-within {
+    transform: translateY(-4px);
+    box-shadow: var(--shadow-md);
+}
+
+.event h3 {
+    font-size: var(--font-size-medium);
+    font-weight: var(--font-weight-bold);
+    color: var(--color-text);
+    line-height: var(--line-height-heading);
+    margin-bottom: var(--spacing-sm);
+}
+
+.event p {
+    line-height: var(--line-height-base);
+    margin-bottom: var(--spacing-sm);
+}
+
+.event p:last-child {
+    margin-bottom: 0;
+}
+
+.event strong {
+    font-weight: var(--font-weight-bold);
+    color: var(--color-accent);
+}
+
+/* ==========================================================================
+   Contact Icons for Kontakt Page
+   Displays icons with text labels (different from footer icon-only style)
+   ========================================================================== */
+
+.section-content .contact-icons {
+    display: flex;
+    flex-wrap: wrap;
+    gap: var(--spacing-md);
+    margin: var(--spacing-md) 0;
+}
+
+.section-content .contact-icon {
+    display: inline-flex;
+    align-items: center;
+    gap: var(--spacing-xs);
+    padding: var(--spacing-sm) var(--spacing-md);
+    text-decoration: none;
+    border-radius: var(--radius-md);
+    transition: transform var(--transition-fast), opacity var(--transition-fast);
+    width: auto;
+    height: auto;
+}
+
+.section-content .contact-icon svg {
+    width: 24px;
+    height: 24px;
+    flex-shrink: 0;
+}
+
+.section-content .contact-icon span {
+    font-size: var(--font-size-base);
+}
+
+.section-content .contact-icon:hover {
+    transform: translateY(-2px);
+    opacity: 0.85;
+}
+
+/* Focus visible styles for accessibility */
+.section-content .contact-icon:focus-visible {
+    outline: var(--focus-ring-width) var(--focus-ring-style) var(--focus-ring-color);
+    outline-offset: var(--focus-ring-offset);
+}
+
+/* ==========================================================================
+   Event with Flyer Layout
+   Displays event text on the left with flyer image on the right INSIDE the box
+   ========================================================================== */
+
+.event.event-with-flyer {
+    display: flex;
+    flex-direction: row;
+    gap: var(--spacing-md);
+    align-items: flex-start;
+}
+
+.event-with-flyer .event-content {
+    flex: 1;
+    min-width: 0;
+}
+
+.event-with-flyer .event-content h3 {
+    font-size: var(--font-size-medium);
+    font-weight: var(--font-weight-bold);
+    color: var(--color-text);
+    line-height: var(--line-height-heading);
+    margin-bottom: var(--spacing-sm);
+}
+
+.event-with-flyer .event-content p {
+    line-height: var(--line-height-base);
+    margin-bottom: var(--spacing-sm);
+}
+
+.event-with-flyer .event-content p:last-child {
+    margin-bottom: 0;
+}
+
+.flyer-image-wrapper {
+    flex-shrink: 0;
+    width: 200px;
+}
+
+.flyer-image-wrapper picture,
+.flyer-image-wrapper img {
+    display: block;
+    width: 100%;
+    height: auto;
+    border-radius: var(--radius-sm);
+}
+
+/* Responsive: Stack vertically on mobile */
+@media (max-width: 767px) {
+    .event.event-with-flyer {
+        flex-direction: column;
+        gap: var(--spacing-md);
+    }
+
+    .flyer-image-wrapper {
+        width: 100%;
+        max-width: 240px;
+    }
+}
